package com.example.dsatracker.dto;import com.example.dsatracker.model.Difficulty;import jakarta.validation.constraints.*;import lombok.*;import java.util.Set;@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builderpublic class ProblemRequestDTO {    @NotNull(message = "LeetCode ID is required")    @Positive(message = "LeetCode ID must be positive")    private Integer leetcodeId;    @NotBlank(message = "Title is required")    @Size(max = 200)    private String title;    @NotNull(message = "Difficulty is required")    private Difficulty difficulty;    @NotBlank(message = "URL is required")    private String url;    @NotEmpty(message = "At least one tag is required")    private Set<Long> tagIds;}